// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the owner (this test contract, set in setUp) and deposit into c via fallback
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        vm.assume(address(c).balance == amount);

        // owner (msg.sender when c was deployed) withdraws everything
        c.withdrawAll();

        // Rule: after any deposit and a owner-call to withdrawAll, the contract holds no ether.
        assertTrue(address(c).balance == 0);
    }

    receive() external payable {}
}
